#[verifier::external_trait_specification]
pub trait ExIteratorEq {
    type ExternalTraitSpecificationFor: core::iter::Iterator;
    type Item;

    fn eq<I>(self, other: I) -> (r: bool)
        where
            I: core::iter::IntoIterator,
            Self::Item: PartialEq<I::Item>,
            Self: Sized,
        default_ensures
            self.obeys_prophetic_iter_laws()
                && self.initial_value_relation(&self)
                && <Self::Item as PartialEqSpec<I::Item>>::obeys_eq_spec()
                ==> {
                    let other_remaining = into_iter_remaining::<I::Item, I>(other);
                    r <==> (
                        self.remaining().len() == other_remaining.len()
                        && forall |i: int| 0 <= i < self.remaining().len() ==>
                            #[trigger] <Self::Item as PartialEqSpec<I::Item>>::eq_spec(
                                &self.remaining()[i],
                                &other_remaining[i],
                            )
                    )
                },
    ;
}

#[verifier::external_trait_specification]
pub trait ExIteratorFindMap {
    type ExternalTraitSpecificationFor: core::iter::Iterator;
    type Item;

    fn find_map<B, F>(&mut self, f: F) -> (r: Option<B>)
        where
            Self: Sized,
            F: FnMut(Self::Item) -> Option<B>
        default_ensures
            final(self).obeys_prophetic_iter_laws() == old(self).obeys_prophetic_iter_laws(),
            final(self).obeys_prophetic_iter_laws() ==>
                final(self).will_return_none() == old(self).will_return_none(),
            final(self).obeys_prophetic_iter_laws() ==>
                (old(self).decrease() is Some <==> final(self).decrease() is Some),
            final(self).obeys_prophetic_iter_laws() ==>
                final(self).remaining().is_suffix_of(old(self).remaining()),
            final(self).obeys_prophetic_iter_laws() && r.is_none() ==> {
                &&& final(self).remaining().len() == 0
                &&& forall |i: int| 0 <= i < old(self).remaining().len() ==>
                    f.ensures((#[trigger] old(self).remaining()[i],), None)
            },
            final(self).obeys_prophetic_iter_laws() && r.is_some() ==> {
                let idx = old(self).remaining().len() - final(self).remaining().len() - 1;
                {
                    &&& 0 <= final(self).remaining().len() < old(self).remaining().len()
                    &&& f.ensures((old(self).remaining()[idx],), r)
                    &&& forall |i: int| 0 <= i < idx ==>
                        f.ensures((#[trigger] old(self).remaining()[i],), None)
                }
            },
    ;
}
